15.     public OrderResult ProcessOrder(Order order)
16.     {
17.         if (order == null)
18.             throw new ArgumentNullException(nameof(order));
19. 
20.         if (order.Items == null || order.Items.Count == 0)
21.             return new OrderResult { Success = false, Error = "No items in order" };
22. 
23.         decimal total = 0;
24.         for (int i = 0; i < order.Items.Count; i++)
25.         {
26.             var item = order.Items[i];
27.             if (item.Quantity <= 0 || item.Price < 0)
28.                 return new OrderResult { Success = false, Error = $"Invalid item at index {i}" };
29. 
30.             var discount = item.Discount ?? 0m;
31.             total += (item.Price - discount) * item.Quantity;
32.         }
33. 
34.         if (total <= 0)
35.             return new OrderResult { Success = false, Error = "Order total must be positive" };
36. 
37.         var payment = _paymentGateway.Charge(order.CustomerId, total);
38.         if (!payment.Succeeded)
39.             return new OrderResult { Success = false, Error = payment.ErrorMessage };
40. 
41.         order.Total = total;
42.         order.Status = OrderStatus.Confirmed;
43.         _repository.Save(order);
44. 
45.         return new OrderResult { Success = true, OrderId = order.Id, Total = total };
46.     }
