52.             return 0;
53. 
54.         decimal total = 0;
55.         foreach (var item in items)
56.         {
57.             if (item.Quantity > 0 && item.Price >= 0)
58.                 total += item.Price * item.Quantity;
59.         }
60.         return total;
61.     }
